export interface AsyncDeps {
  /** Asks the configured model; absent when no provider is available. */
  completer?: Completer;
  aiTimeoutMs?: number;
  /** An operator cancel (Ctrl-C) while the model is being asked: the merge does not start. */
  signal?: AbortSignal;
